  "evento_id": "e_25ba50",
  "view_hash": "bf9e11b9d024fb760e0ab17425037c56d1fbbc4bf90227b29ce10842715b94b2",
  "fim_base": {
    "estado": "exato",
    "valor": 12,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [],
    "motivo": "Término da linha base declarado como D12.",
    "unidade": "dia_corrido"
  },
  "fim_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_f7ff82",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "A ficha d_a70f, indicada como fonte de todas as precedências, não está disponível; sem essas relações não é possível calcular o término após a redução da duração do dossiê."
    ],
    "motivo": "O aviso reduz a duração de Emitir dossiê, mas as precedências necessárias para calcular o término final não foram fornecidas.",
    "unidade": "dia_corrido"
  },
  "delta_dias": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      },
      {
        "fonte_id": "f_f7ff82",
        "localizador": "L01"
      }
    ],
    "lacunas": [
      "Faltam as precedências da ficha d_a70f, portanto não se pode determinar se a redução da atividade altera o término final nem quantificar a variação."
    ],
    "motivo": "A linha base é conhecida, mas o término novo não pode ser calculado com as relações de precedência ausentes.",
    "unidade": "dia_corrido"
  },
  "custo_base": {
    "estado": "exato",
    "valor": 165000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [],
    "motivo": "Custo da linha base declarado como R$ 1.650,00.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "exato",
    "valor": 165000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_f7ff82",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      }
    ],
    "lacunas": [],
    "motivo": "O aviso não tem custo direto; as parcelas fixas não variam com o prazo e a política sem crédito preserva o valor contratado do apoio em caso de antecipação. As obrigações listadas esgotam os custos.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "exato",
    "valor": 0,
    "direcao": "zero",
    "evidencias": [
      {
        "fonte_id": "f_f7ff82",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [],
    "motivo": "O aviso não adiciona custo, e eventual antecipação não gera crédito no apoio; assim, o custo permanece igual ao da linha base.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "A redução de duração do dossiê está documentada, mas as precedências necessárias para calcular o término final não estão disponíveis. O custo permanece igual à linha base: não há custo direto no aviso, as parcelas fixas não variam com o prazo e a política do apoio não concede crédito por antecipação."
}

